     fun openExternally(file: File) {
         val intent = externalIntent(file, Intent.ACTION_VIEW)
         if (intent == null) {
             showNotice("нет приложения, открывающего ${FileTree.ext(file).ifEmpty { "этот тип" }}")
             return
