class OpenCodeConfigTest {
  @get:Rule val tmp = TemporaryFolder()
  private fun ws() = Workspace.at(tmp.newFolder())

  @Test fun mergesGlobalAndProjectWithProjectWinning() {
    val w = ws()
    File(w.root, "opencode").mkdirs()
    File(w.root, "opencode/opencode.json").writeText("""{"model":"global-model","permission":{"bash":"ask"}}""")
    val proj = File(w.root, "proj").apply{mkdirs()}
    File(proj, ".opencode").mkdirs()
    File(proj, ".opencode/opencode.json").writeText("""{"model":"project-model","permission":{"bash":"allow"}}""")
    val cfg = OpenCodeConfig.load(w, proj)
    assertEquals("project-model", cfg.model)
    assertEquals(OpenCodeConfig.Permission.ALLOW, cfg.permissionFor("bash","rm -rf /"))
  }

  @Test fun patternedPermissionMostSpecificWins() {
    ... permission bash: {"*":"allow","rm *":"deny","git status":"allow"}
    assertEquals(DENY, permissionFor("bash","rm -rf x"))
    assertEquals(ALLOW, permissionFor("bash","ls"))
    assertEquals(ALLOW, permissionFor("bash","git status"))
  }

  @Test fun fileToolPermissionMatchesPath() {
    permission edit: {"*.md":"deny","*":"allow"}
    assertEquals(DENY, permissionFor("edit","README.md"))
    assertEquals(ALLOW, permissionFor("edit","src/Main.kt"))
