             Text(
                 "План задач",
                 style = MaterialTheme.typography.labelMedium,
                 color = MaterialTheme.colorScheme.onSecondaryContainer,
             )
             Spacer(Modifier.height(4.dp))
             todos.take(12).forEach { todo ->
                 Row(verticalAlignment = Alignment.Top) {
                     val mark = when {
                         todo.isDone -> "✓"
                         todo.isActive -> "◐"
