                     }
                     val color = when {
                         todo.isDone -> MaterialTheme.colorScheme.onSurfaceVariant
                         todo.isActive -> MaterialTheme.colorScheme.primary
                         else -> MaterialTheme.colorScheme.onSurfaceVariant
