             ) {
                 Icon(Icons.Filled.AttachFile, contentDescription = "Отправить файл агенту")
             }
             IconButton(
                 onClick = { showAgentPicker = true },
                 enabled = !answering,
             ) {
                 Icon(Icons.Filled.Person, contentDescription = "Выбрать агента")
